// Fuente para el escenario resumido en PNG.
//
// Satori (el motor detras de `next/og`) NO usa fuentes del sistema: hay que pasarle el
// archivo. Va embebida en base64 por la misma razon que el logo — los PNG se generan en
// funciones serverless, donde leer de public/ no esta garantizado.
//
// Es Inter, subsetada a los caracteres que usamos (latin + acentos del espanol + simbolos
// de moneda y puntuacion). La tipografia oficial de la marca es Atyp; cuando tengamos el
// archivo, se sustituye aqui y en los PDFs.
const INTER_400_B64 =
  '';
const INTER_700_B64 =
  '';

function aBytes(b64: string): ArrayBuffer {
  const bin = Buffer.from(b64, 'base64');
  return bin.buffer.slice(bin.byteOffset, bin.byteOffset + bin.byteLength) as ArrayBuffer;
}

/** Listo para pasar a `new ImageResponse(..., { fonts })`. */
export function fuentesResumen() {
  return [
    { name: 'Inter', data: aBytes(INTER_400_B64), weight: 400 as const, style: 'normal' as const },
    { name: 'Inter', data: aBytes(INTER_700_B64), weight: 700 as const, style: 'normal' as const },
  ];
}
